export const title = "How to Reduce Keyboard Noise in a Shared Home Office";
export const metaTitle = "How to Reduce Keyboard Noise in a Shared Home";
export const metaDescription = "Reduce keyboard noise in a shared office by separating airborne sound, desk vibration, and call pickup before choosing upgrades.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-17";
